 const r=await F.compileCustomerFactory(),newA=parse(r.code),newInit=one(newA,n=>ts.isVariableDeclaration(n)&&n.name.getText(newA)==='__CUSTOMER_WORKBENCH_EXPORTS','compiled factory').initializer;
